-- 000057_seed_move_commands_third_wave.down.sql
-- M14-03e: 第三波 6 キャラの command 索引 move_commands の seed(非派生のみ)
-- 本ファイルは cmd/seedgen が character_data/*.csv から生成した成果物(手編集しない)。
-- 非派生技(is_derived=false)のみ搭載。token_key は numpad 正規化済み(internal/moveindex が一元管理)。
-- 索引は広く持つ(必殺技・空中技も搭載)＝段階2 スコープへの絞り込みは消費者側(CHANGE-069 §1.5-6)。
-- 既存マイグレは非改変(新規連番で追加)。FK 依存順 characters→moves→move_commands。

-- ===== jp =====
DELETE FROM move_commands WHERE move_id IN (
    SELECT m.id FROM moves m JOIN characters c ON c.id = m.character_id WHERE c.code = 'jp' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6') AND m.code IN ('sa2_lovushka', 'departure_heavy', 'embrace', 'embrace_od', 'departure_light', 'departure_medium', 'departure_od', 'triglav_heavy', 'amnesia', 'amnesia_od', 'triglav_light', 'triglav_medium', 'triglav_od', 'sa3_interdiction', 'ca_interdiction', 'sa1_chornobog', 'torbalan_heavy', 'stribog_heavy', 'torbalan_od', 'torbalan_light', 'stribog_light', 'torbalan_medium', 'stribog_medium', 'stribog_od', 'crouching_heavy_kick', 'crouching_heavy_punch', 'crouching_light_kick', 'crouching_light_punch', 'crouching_medium_kick', 'crouching_medium_punch', 'malice', 'throw_back', 'grom_strelka_1hit', 'throw_forward', 'bylina', 'guillotinna', 'standing_heavy_kick', 'jumping_heavy_kick', 'standing_heavy_punch', 'jumping_heavy_punch', 'drive_impact', 'standing_light_kick', 'jumping_light_kick', 'standing_light_punch', 'jumping_light_punch', 'tornado', 'standing_medium_kick', 'jumping_medium_kick', 'standing_medium_punch', 'jumping_medium_punch', 'drive_parry'));

